import{z as i,x as o,o as A,c as d,q as t,j as B,D as s,d as E,s as l,S as r,b as e}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"共识与复制状态机","description":"","frontmatter":{"title":"共识与复制状态机","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/con-consensus-rsm.md","filePath":"cs/con-consensus-rsm.md","lastUpdated":1791413859000}'),p={name:"cs/con-consensus-rsm.md"};function c(C,a,m,D,h,u){const n=o("Mermaid");return A(),d("div",null,[a[2]||(a[2]=t('<h1 id="共识与复制状态机" tabindex="-1">共识与复制状态机 <a class="header-anchor" href="#共识与复制状态机" aria-label="Permalink to &quot;共识与复制状态机&quot;">​</a></h1><div class="epigraph"><p>共识只决定日志的顺序；把日志变成服务的一切——确定性执行、不确定性入日志、对客户端恰好一次——都是状态机侧的合同，也是共识优化到头之后剩下的硬界。</p><footer>—— 据 Schneider, ACM Computing Surveys, 1990 与 Ongaro 博士论文, 2014 整理</footer></div><p><a href="/cs/con-linearity-testing">上一课</a>给了检验历史的工具，但用户看到的不是日志而是状态机的输出。主干课的<a href="/cs/replicated-state-machine">复制状态机</a>立过「同一确定性 \\(\\delta\\)、同一已提交日志」的骨架；本课拆共识引擎与状态机之间的接缝：提交与应用的错位、非确定性怎么进日志、客户端重试怎么收到恰好一次。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>两个 index 永远错位：共识推进到 commitIndex \\(c\\)，状态机应用到 lastApplied \\(a\\)，而 \\(a \\lt c\\) 是常态——复制是网络上的多数派确认，应用要执行业务逻辑。错位裂出三条缝。第一是读：领导者知道 \\(c\\)，状态机只走到 \\(a\\)，刚提交的写还没生效，读状态机会拿到旧值，读自己写破裂。第二是副作用：apply 异步，崩溃重启后从快照加重放恢复，重放会把「发邮件、扣款」再执行一遍——共识保证日志不重不丢，不保证副作用不重。第三是客户端：RPC 超时后重试同一命令，若不去重，日志里两条条目、状态机执行两次。</p><p><span class="marginnote">数字实例：日志第 10 条已提交（\\(c=10\\)），状态机才应用到第 7 条（\\(a=7\\)）。此刻任何读状态机的请求，看到的都是第 7 条之后的世界——第 8 到 10 条「已确定但还没生效」。用户刚写入就立刻去读，读到的却是旧值，这就是「读自己写破裂」的具体来源。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>接缝三件事。其一，应用管线：已提交条目按序交给状态机，apply 异步推进，进度本身要持久化或从快照恢复——重启后从快照记录的 applied index 继续，重放只补未应用段。其二，非确定性全走日志：时间戳、随机数、自增号、外部调用的返回值，要么由领导者提议进日志再统一采用，要么把「含结果的完整记录」作为日志条目；\\(\\delta\\) 保持纯函数，同一日志在任何副本推出同一状态。其三，会话去重：每客户端唯一 ID 加单调序列号，状态机维护「每会话最近已执行序列号与响应缓存」，重试命中即返回缓存响应——恰好一次从这里来。去重表是状态机状态的一部分，必须进快照，否则重启后的重放又执行一遍。</p><p><span class="marginnote">术语翻译：非确定性操作就是「同样输入、换个时间跑结果就不同」的操作：取当前时间、生成随机数、读自增计数、调外部接口。确定性 \\(\\delta\\) 像菜谱——同一份备料（日志），任何厨师（副本）做出的菜都一样；所以这些「看天气」的步骤必须先写进备料单（日志），副本照单执行。</span></p><p><span class="marginnote">Raft 论文建议的会话去重最容易被漏掉一半：响应缓存要有界——领导者换了、会话过期了就作废缓存并让客户端重建会话；无界缓存本身就是新的故障面。</span></p>',10)),(A(),B(r,null,{default:s(()=>[l(n,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20CLI%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%E5%91%BD%E4%BB%A4%EF%BC%9AID%20%E5%8A%A0%E5%BA%8F%E5%88%97%E5%8F%B7%22%5D%20--%3E%20LEAD%5B%22%E9%A2%86%E5%AF%BC%E8%80%85%E8%BF%BD%E5%8A%A0%E6%97%A5%E5%BF%97%22%5D%0A%20%20LEAD%20--%3E%20QUO%5B%22%E5%A4%9A%E6%95%B0%E6%B4%BE%E7%A1%AE%E8%AE%A4%EF%BC%9AcommitIndex%20%E6%8E%A8%E8%BF%9B%22%5D%0A%20%20QUO%20--%3E%20PIPE%5B%22%E5%BA%94%E7%94%A8%E7%AE%A1%E7%BA%BF%EF%BC%9A%E6%8C%89%E5%BA%8F%E4%BA%A4%E7%BB%99%E7%8A%B6%E6%80%81%E6%9C%BA%22%5D%0A%20%20PIPE%20--%3E%20DEDUP%7B%22%E5%BA%8F%E5%88%97%E5%8F%B7%E5%B7%B2%E6%89%A7%E8%A1%8C%EF%BC%9F%22%7D%0A%20%20DEDUP%20--%3E%7C%E6%98%AF%7C%20CACHE%5B%22%E8%BF%94%E5%9B%9E%E7%BC%93%E5%AD%98%E7%9A%84%E5%93%8D%E5%BA%94%22%5D%0A%20%20DEDUP%20--%3E%7C%E5%90%A6%7C%20EXEC%5B%22%E6%89%A7%E8%A1%8C%E5%B9%B6%E7%BC%93%E5%AD%98%E5%93%8D%E5%BA%94%22%5D%0A%20%20EXEC%20--%3E%20SM%5B%22%E7%8A%B6%E6%80%81%E6%9C%BA%E6%8E%A8%E8%BF%9B%20lastApplied%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[E("读路径的账在 \\(a\\) 与 \\(r\\) 之间：ReadIndex 给出读序号 \\(r \\le c\\)，实现要等状态机追到 \\(a \\ge r\\) 才应答——排队而非猜测；租约读同样受 \\(a\\) 约束，租约过期就必须退回心跳确认。这就是优化到头剩下的硬界：写延迟的下限是一轮多数派确认，读的新鲜度下限由 apply 进度决定，共识侧的聪明绕不过其中任何一条。快照是接缝的另一件工具：状态机在某时刻的全量镜像压缩日志、缩短重放，安装快照就是强制对齐 \\(a\\)；历史检验里常见的读旧值违例，来源常在快照安装与 apply 进度的交接处。对外部世界的写没有撤销语义，副作用应当改写成「日志携带动作、状态机代发」，并配"),e("a",{href:"/cs/idempotency-keys"},"幂等键"),E("与 "),e("a",{href:"/cs/distributed-lock-fencing"},"fencing"),E("——日志回滚也收不回已经发出的邮件。")],-1)),(A(),B(r,null,{default:s(()=>[l(n,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20WRT%5B%22%E5%86%99%E5%B7%B2%E6%8F%90%E4%BA%A4%3A%20commitIndex%20c%20%E6%8E%A8%E8%BF%9B%22%5D%20--%3E%20GAP%5B%22apply%20%E5%BC%82%E6%AD%A5%3A%20lastApplied%20a%20%E5%9C%A8%E8%BF%BD%22%5D%0A%20%20GAP%20--%3E%20RD%5B%22%E8%AF%BB%E8%AF%B7%E6%B1%82%E6%8B%BF%E5%88%B0%20ReadIndex%20%E5%BA%8F%E5%8F%B7%20r%22%5D%0A%20%20RD%20--%3E%20CHK%7B%22%E7%8A%B6%E6%80%81%E6%9C%BA%E5%B7%B2%E8%BF%BD%E5%88%B0%20a%20%E2%89%A5%20r%20%3F%22%7D%0A%20%20CHK%20--%3E%7C%22%E5%90%A6%22%7C%20WAIT%5B%22%E6%8E%92%E9%98%9F%E7%AD%89%E5%BE%85%2C%20%E8%80%8C%E9%9D%9E%E7%8C%9C%E6%B5%8B%E6%97%A7%E5%80%BC%22%5D%0A%20%20CHK%20--%3E%7C%22%E6%98%AF%22%7C%20ANS%5B%22%E5%BA%94%E7%AD%94%E6%96%B0%E9%B2%9C%E5%80%BC%22%5D%0A%20%20WAIT%20--%3E%20ANS%0A"})]),fallback:s(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<p><span class="marginnote">常见误区：初学者容易以为「日志已提交」就等于「数据可读」。两者之间隔着一条 apply 管线：提交是共识层的事（多数派确认），生效是状态机层的事（按序执行）。读请求的新鲜度由 \\(a\\) 决定，不由 \\(c\\) 决定——这条界就是本课说的「硬界」之一。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>确定性之外共识救不了：状态机自身的 bug、运行时的非确定 GC、跨状态机的顺序依赖，都会让「同一日志」推出不同状态；跨组事务与隔离级别另有专课，跨组原子性的起点是<a href="/cs/consensus-vs-2pc">共识与 2PC</a>。本课也不重写 RSM 定义与读档位（第一课已给三档读），只钉接缝：错位、去重、快照交接。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(a \\lt c\\) 是常态：读的新鲜度由 apply 进度决定，不由 commitIndex 决定。</li><li>非确定性必须进日志，\\(\\delta\\) 纯函数化；否则同一日志在副本间推出不同状态。</li><li>恰好一次靠会话 ID、序列号与有界响应缓存；去重表要进快照。</li><li>副作用改写成「日志携带动作、状态机代发」，配幂等键与 fencing。</li><li>出处：Schneider, ACM Computing Surveys 1990；Ongaro 博士论文 2014（客户端会话一节）。</li></ul>',5))])}const _=i(p,[["render",c]]);export{F as __pageData,_ as default};
